-- Restituye exactamente los cuerpos previos; no revierte datos.
-- ADVERTENCIA: reabre lectura de owner/creator inactivo; requiere decisión consciente.
SET LOCAL lock_timeout='1s';
SET LOCAL statement_timeout='4s';
DO $crm_call_membership_delta$
DECLARE v_item jsonb; v_patch jsonb; v_oid oid; v_source text; v_definition text; v_metadata jsonb; v_current jsonb;
BEGIN
 FOR v_item IN SELECT value FROM jsonb_array_elements($crm_call_membership_manifest$[{"signature":"public.crm_calls_list(integer,jsonb)","acl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}","config":["search_path=public, pg_temp"],"owner":"postgres","security_definer":true,"before":"d687303712bed32ba1d17ec07bfe35cc","after":"2645f28d3f4335dca1af203e17ae963b","definition":"CREATE OR REPLACE FUNCTION public.crm_calls_list(p_org integer, p_filters jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\ndeclare v_all boolean; v_user uuid; v_q text:=nullif(trim(p_filters->>'q'),''); v_result jsonb;\nbegin\n  perform public.fn_assert_acceso_org(p_org);\n  v_all:=auth.uid() is null or public.fn_crm_tiene_permiso(p_org,'crm.calls.view_all');\n  v_user:=nullif(p_filters->>'user_id','')::uuid;\n  if not v_all then\n    if v_user is not null and v_user<>auth.uid() then raise exception using errcode='42501',message='sin_permiso'; end if;\n    v_user:=auth.uid();\n  end if;\n  with filtered as materialized (\n    select c.* from public.calls c where c.organization_id=p_org\n      and (v_user is null or c.user_id=v_user)\n      -- La RPC es SECURITY DEFINER: replica el alcance restrictivo del listado.\n      and (auth.uid() is null or (\n        (c.customer_id is null or exists(select 1 from public.customers cu where cu.id=c.customer_id and cu.organization_id=p_org\n          and (cu.branch_id is null or exists(select 1 from public.branches b where b.id=cu.branch_id and b.organization_id=p_org))\n          and public.app_branch_access(cu.branch_id::integer)))\n        and (c.opportunity_id is null or exists(select 1 from public.opportunities o where o.id=c.opportunity_id and o.organization_id=p_org\n          and o.customer_id is not distinct from c.customer_id\n          and (o.branch_id is null or exists(select 1 from public.branches b where b.id=o.branch_id and b.organization_id=p_org))\n          and public.app_branch_access(o.branch_id::integer)))\n      ))\n      and (not(p_filters?'status') or c.status=p_filters->>'status')\n      and (not(p_filters?'direction') or c.direction=p_filters->>'direction')\n      and (not(p_filters?'mode') or c.mode=p_filters->>'mode')\n      and (not(p_filters?'customer_id') or c.customer_id=(p_filters->>'customer_id')::uuid)\n      and (not(p_filters?'opportunity_id') or c.opportunity_id=(p_filters->>'opportunity_id')::uuid)\n      and (not(p_filters?'provider_call_sid') or c.provider_call_sid=p_filters->>'provider_call_sid')\n      and (not(p_filters?'outcome') or c.metadata->>'disposition_outcome'=p_filters->>'outcome')\n      and (not(p_filters?'from_date') or c.started_at>=(p_filters->>'from_date')::timestamptz)\n      and (not(p_filters?'to_date') or case when coalesce((p_filters->>'to_date_exclusive')::boolean,false)\n        then c.started_at<(p_filters->>'to_date')::timestamptz else c.started_at<=(p_filters->>'to_date')::timestamptz end)\n      and (not(p_filters?'has_recording') or exists(select 1 from public.call_recordings r where r.organization_id=p_org and r.call_id=c.id and r.status='ready')=(p_filters->>'has_recording')::boolean)\n      and (v_q is null or position(lower(v_q) in lower(c.from_number))>0 or position(lower(v_q) in lower(c.to_number))>0\n        or exists(select 1 from public.customers cu where cu.organization_id=p_org and cu.id=c.customer_id and position(lower(v_q) in lower(cu.full_name))>0)\n        or exists(select 1 from public.call_transcripts tr where tr.organization_id=p_org and tr.call_id=c.id and tr.status='completed'\n          and to_tsvector('simple'::regconfig,coalesce(tr.full_text,'')) @@ websearch_to_tsquery('simple'::regconfig,v_q)))\n  ), page as (\n    select * from filtered order by started_at desc,id limit least(200,greatest(1,coalesce((p_filters->>'limit')::integer,50)))\n    offset greatest(0,coalesce((p_filters->>'offset')::integer,0))\n  )\n  select jsonb_build_object('count',(select count(*) from filtered),'canViewAll',v_all,\n    'stats',jsonb_build_object('totalToday',(select count(*) from filtered),\n      'avgDuration',coalesce((select round(avg(duration_seconds) filter(where duration_seconds>0 and status='completed' and (answered_at is not null or answered_by='human' or mode='manual'))) from filtered),0),\n      'missed',(select count(*) from filtered where status in('no_answer','busy','canceled','failed','voicemail')),\n      'answered',(select count(*) from filtered where answered_by='human'),\n      'voiceSeconds',coalesce((select sum(duration_seconds) from filtered where mode<>'manual' and status='completed'),0),\n      'remainingVoiceMinutes',(select voice_minutes_remaining from public.comm_settings where organization_id=p_org and is_active limit 1),\n      'voiceConfigured',exists(select 1 from public.comm_settings where organization_id=p_org and is_active)),\n    'data',coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object(\n      'customer',(select jsonb_build_object('id',cu.id,'full_name',cu.full_name,'first_name',cu.first_name,'last_name',cu.last_name,'phone',cu.phone) from public.customers cu where cu.id=c.customer_id and cu.organization_id=p_org),\n      'opportunity',(select jsonb_build_object('id',o.id,'name',o.name) from public.opportunities o where o.id=c.opportunity_id and o.organization_id=p_org),\n      'user',(select jsonb_build_object('id',pr.id,'first_name',pr.first_name,'last_name',pr.last_name,'email',pr.email) from public.profiles pr where pr.id=c.user_id),\n      'recordings',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'status',r.status,'duration_seconds',r.duration_seconds,'channels',r.channels)) from public.call_recordings r where r.call_id=c.id and r.organization_id=p_org and r.status<>'deleted'),'[]'::jsonb),\n      'analysis',(select jsonb_build_object('summary',a.summary,'sentiment',a.sentiment,'detected_objections',a.detected_objections) from public.call_analyses a where a.call_id=c.id and a.organization_id=p_org\n        and (a.transcript_id is null or exists(select 1 from public.call_transcripts t where t.id=a.transcript_id and t.organization_id=a.organization_id and t.call_id=a.call_id))\n        order by a.created_at desc,a.id limit 1),\n      'consent_method',(select co.method from public.call_consents co where co.call_id=c.id and co.organization_id=p_org and co.consent_type='recording' order by co.announced_at desc,co.id limit 1),\n      'disposition_outcome',c.metadata->>'disposition_outcome'\n    ) order by c.started_at desc,c.id) from page c),'[]'::jsonb)) into v_result;\n  return v_result;\nend; $function$\n"}]$crm_call_membership_manifest$::jsonb) LOOP
  v_oid:=to_regprocedure(v_item->>'signature');
  IF v_oid IS NULL THEN RAISE EXCEPTION 'rpc_llamadas_ausente' USING ERRCODE='P0001'; END IF;
  SELECT p.prosrc,(to_jsonb(p)-'prosrc'-'proargdefaults') || jsonb_build_object('function_arguments',pg_get_function_arguments(p.oid),'default_ast_without_locations',regexp_replace(p.proargdefaults::text,':location -?[0-9]+',':location <offset>','g')) INTO v_source,v_metadata FROM pg_proc p WHERE p.oid=v_oid;
  IF (SELECT p.proacl::text FROM pg_proc p WHERE p.oid=v_oid) IS DISTINCT FROM v_item->>'acl'
   OR (SELECT to_jsonb(p.proconfig) FROM pg_proc p WHERE p.oid=v_oid) IS DISTINCT FROM v_item->'config'
   OR (SELECT pg_get_userbyid(p.proowner) FROM pg_proc p WHERE p.oid=v_oid) IS DISTINCT FROM v_item->>'owner'
   OR (SELECT p.prosecdef FROM pg_proc p WHERE p.oid=v_oid) IS DISTINCT FROM (v_item->>'security_definer')::boolean THEN
   RAISE EXCEPTION 'contrato_rpc_llamadas_modificado' USING ERRCODE='P0001'; END IF;
  IF md5(v_source)=v_item->>'after' THEN CONTINUE; END IF;
  IF md5(v_source) IS DISTINCT FROM v_item->>'before' THEN
   RAISE EXCEPTION 'fuente_rpc_llamadas_modificada' USING ERRCODE='P0001'; END IF;
  v_definition:=v_item->>'definition';
  EXECUTE v_definition;
  SELECT p.prosrc,(to_jsonb(p)-'prosrc'-'proargdefaults') || jsonb_build_object('function_arguments',pg_get_function_arguments(p.oid),'default_ast_without_locations',regexp_replace(p.proargdefaults::text,':location -?[0-9]+',':location <offset>','g')) INTO v_source,v_current FROM pg_proc p WHERE p.oid=v_oid;
  IF md5(v_source) IS DISTINCT FROM v_item->>'after' OR v_metadata IS DISTINCT FROM v_current THEN
   RAISE EXCEPTION 'contrato_rpc_llamadas_no_conservado' USING ERRCODE='P0001'; END IF;
 END LOOP;
END;
$crm_call_membership_delta$;
